-- RUC-01.P1 / OFFLINE SOURCE ONLY, SQL Server2022/compat160.
-- Requires exact accepted V14, separate CONTROL principal, one EXTERNAL
-- committable transaction and caller stop-on-first-error across all GO batches.
-- No legacy RUC map is accepted by this package: ANY existing tenant aborts
-- BACKFILL_REQUIRED BEFORE DDL. No fabricated/default RUC or data remediation.
-- V1-V14 immutable. Object ALTER preserves ACL; only four new public SPs
-- receive object EXECUTE GRANT runtime / DENY bootstrap (+8 role ACL).
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
SET NOCOUNT ON;
IF @@TRANCOUNT=0 OR XACT_STATE()<>1 THROW 51000,N'HP_INVALID:External committable migration transaction required',1;
IF TRY_CONVERT(int,SERVERPROPERTY('ProductMajorVersion'))<>16 OR (SELECT compatibility_level FROM sys.databases WHERE database_id=DB_ID())<>160
 THROW 51000,N'HP_INVALID:SQL Server2022 compatibility160 required',1;
IF ISNULL(HAS_PERMS_BY_NAME(DB_NAME(),N'DATABASE',N'CONTROL'),0)<>1
 OR ISNULL(IS_ROLEMEMBER(N'hp_runtime_executor'),0)=1 OR ISNULL(IS_ROLEMEMBER(N'hp_bootstrap_executor'),0)=1
 THROW 51001,N'HP_FORBIDDEN:Separate CONTROL migration principal required',1;
IF NOT EXISTS(SELECT 1 FROM sys.schemas WHERE name COLLATE Latin1_General_100_BIN2=N'dbo' AND DATALENGTH(name)=6 AND principal_id=1)
 OR NOT EXISTS(SELECT 1 FROM sys.database_principals p JOIN sys.databases d ON d.database_id=DB_ID() AND p.sid=d.owner_sid
 WHERE p.principal_id=1 AND p.name=N'dbo' AND ((p.type='S' AND p.authentication_type=1) OR (p.type='U' AND p.authentication_type=3)))
 OR (SELECT COUNT(*) FROM sys.database_principals WHERE name IN (N'hp_runtime_executor',N'hp_bootstrap_executor') AND type='R' AND is_fixed_role=0 AND owning_principal_id=1)<>2
 THROW 51000,N'HP_INVALID:Accepted dbo ownership and executor roles required',1;
IF COL_LENGTH(N'dbo.tenants',N'ruc') IS NOT NULL OR COL_LENGTH(N'dbo.tenants',N'profile_revision') IS NOT NULL
 OR OBJECT_ID(N'dbo.usp_tenant_session_save') IS NOT NULL OR OBJECT_ID(N'dbo.usp_tenant_space_resolve') IS NOT NULL OR OBJECT_ID(N'dbo.usp_identity_tenant_ruc_lock') IS NOT NULL OR OBJECT_ID(N'dbo.usp_tenant_profile_save') IS NOT NULL
 OR OBJECT_ID(N'dbo.UQ_tenants_ruc') IS NOT NULL OR OBJECT_ID(N'dbo.CK_tenants_ruc') IS NOT NULL OR OBJECT_ID(N'dbo.DF_tenants_profile_revision') IS NOT NULL OR OBJECT_ID(N'dbo.CK_tenants_profile_revision') IS NOT NULL
 THROW 51003,N'HP_CONFLICT:RUC migration collision; no reapply or repair',1;
-- Exact module normalization: CRLF/loneCR -> LF, trim exterior ASCII
-- whitespace only; compare full canonical batch OR statement without its
-- leading comments. Both are explicit UTF16LE SHA256 pins, no SQL rewrite.
DECLARE @modules TABLE(name sysname PRIMARY KEY,full_hash char(64),statement_hash char(64));
