 WHERE NOT EXISTS(SELECT 1 FROM sys.database_permissions p WHERE p.class=1 AND p.major_id=OBJECT_ID(N'dbo.'+t.name,N'U') AND p.minor_id=0 AND p.grantee_principal_id=role_id.id AND p.permission_name=perm.name AND p.state='D'))
 THROW 51000,N'HP_INVALID:Accepted runtime business-table DENYs required',1;
DECLARE @history int=OBJECT_ID(N'dbo.flyway_schema_history',N'U');
IF @history IS NOT NULL AND (
 NOT EXISTS(SELECT 1 FROM sys.database_permissions WHERE class=1 AND major_id=@history AND minor_id=0 AND grantee_principal_id=DATABASE_PRINCIPAL_ID(N'hp_runtime_executor') AND permission_name=N'VIEW DEFINITION' AND state='G')
 OR EXISTS(SELECT 1 FROM (VALUES(DATABASE_PRINCIPAL_ID(N'hp_runtime_executor')),(DATABASE_PRINCIPAL_ID(N'hp_bootstrap_executor'))) role_id(id) CROSS APPLY(VALUES(N'SELECT'),(N'INSERT'),(N'UPDATE'),(N'DELETE')) perm(name)
 WHERE NOT EXISTS(SELECT 1 FROM sys.database_permissions WHERE class=1 AND major_id=@history AND minor_id=0 AND grantee_principal_id=role_id.id AND permission_name=perm.name AND state='D')))
 THROW 51000,N'HP_INVALID:Accepted optional history permissions required',1;
