 THROW 51000,N'HP_INVALID:Unexpected executor permission delta',1;
DECLARE @link_shape TABLE(ordinal int,name sysname,type_name sysname,size smallint,collation_name sysname NULL);
INSERT @link_shape VALUES (1,N'tenant_id',N'char',36,N'Latin1_General_100_BIN2'),(2,N'patient_id',N'char',36,N'Latin1_General_100_BIN2'),(3,N'user_id',N'char',36,N'Latin1_General_100_BIN2'),(4,N'relationship',N'nvarchar',160,N'Latin1_General_100_CI_AI_SC'),(5,N'active',N'bit',1,NULL),(6,N'scopes',N'nvarchar',-1,N'Latin1_General_100_BIN2'),(7,N'revision',N'int',4,NULL);
IF EXISTS(SELECT 1 FROM @link_shape e LEFT JOIN sys.columns c ON c.object_id=@l AND c.column_id=e.ordinal WHERE c.column_id IS NULL OR c.name COLLATE Latin1_General_100_BIN2<>e.name COLLATE Latin1_General_100_BIN2 OR TYPE_NAME(c.system_type_id)<>e.type_name OR c.user_type_id<>c.system_type_id OR c.max_length<>e.size OR c.is_nullable<>0 OR c.is_computed<>0 OR c.is_identity<>0 OR c.generated_always_type<>0 OR ISNULL(c.collation_name,N'') COLLATE Latin1_General_100_BIN2<>ISNULL(e.collation_name,N'') COLLATE Latin1_General_100_BIN2)
 OR NOT EXISTS(SELECT 1 FROM sys.indexes i WHERE i.object_id=@l AND i.is_primary_key=1 AND i.is_unique=1 AND i.is_disabled=0 AND (SELECT COUNT(*) FROM sys.index_columns WHERE object_id=@l AND index_id=i.index_id AND key_ordinal>0)=3 AND EXISTS(SELECT 1 FROM sys.index_columns WHERE object_id=@l AND index_id=i.index_id AND key_ordinal=1 AND column_id=1) AND EXISTS(SELECT 1 FROM sys.index_columns WHERE object_id=@l AND index_id=i.index_id AND key_ordinal=2 AND column_id=2) AND EXISTS(SELECT 1 FROM sys.index_columns WHERE object_id=@l AND index_id=i.index_id AND key_ordinal=3 AND column_id=3))
 OR (SELECT COUNT(*) FROM sys.foreign_keys WHERE parent_object_id=@l AND is_disabled=0 AND is_not_trusted=0)<>2
 THROW 51000,N'HP_INVALID:Exact V14 link shape/key/foreign keys required',1;

-- All current tenants are legacy because the RUC column is not present.
-- HOLDLOCK retains the empty key range through DDL and caller completion.
IF EXISTS(SELECT 1 FROM dbo.tenants WITH(UPDLOCK,HOLDLOCK))
 THROW 51003,N'HP_CONFLICT:BACKFILL_REQUIRED authorized legacy RUC mapping required',1;
ALTER TABLE dbo.tenants ADD ruc varchar(11) COLLATE Latin1_General_100_BIN2 NOT NULL;
ALTER TABLE dbo.tenants ADD profile_revision int NOT NULL CONSTRAINT DF_tenants_profile_revision DEFAULT(1) WITH VALUES;
GO
ALTER TABLE dbo.tenants WITH CHECK ADD CONSTRAINT CK_tenants_ruc CHECK(DATALENGTH(ruc)=11 AND ruc COLLATE Latin1_General_100_BIN2 NOT LIKE '%[^0-9]%');
ALTER TABLE dbo.tenants ADD CONSTRAINT UQ_tenants_ruc UNIQUE(ruc);
GO
ALTER TABLE dbo.tenants WITH CHECK ADD CONSTRAINT CK_tenants_profile_revision CHECK(profile_revision>=1);
GO
ALTER PROCEDURE dbo.usp_tenant_by_slug @slug varchar(63)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 SELECT t.id,t.name,t.slug,t.kind,t.domain,t.status,v.modules,t.ruc,t.profile_revision AS revision FROM dbo.tenants t JOIN dbo.subscriptions s ON s.tenant_id=t.id JOIN dbo.plan_versions v ON v.plan_id=s.plan_id AND v.version=s.plan_version WHERE t.slug=@slug;
END;
GO
ALTER PROCEDURE dbo.usp_platform_tenants @tenant_id char(36)=NULL,@limit int=100
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_actor @roles=N'SAD',@platform_only=1; SET @limit=CASE WHEN @limit IS NULL THEN 100 WHEN @limit<1 THEN 1 WHEN @limit>200 THEN 200 ELSE @limit END; SELECT TOP(@limit) t.id,t.name,t.slug,t.kind,t.domain,t.status,t.owner_user_id,t.timezone,t.created_at,u.name owner_name,u.email owner_email,s.plan_id,s.plan_version,s.cycle,s.branch_quota,s.professional_quota,s.specialty_quota,s.renewal_date,p.name plan_name,v.modules,v.base_minor,v.branch_minor,v.professional_minor,v.included_branches,v.included_professionals,v.annual_discount,(SELECT COUNT_BIG(*) FROM dbo.branches b WHERE b.tenant_id=t.id AND b.active=1 AND b.[external]=0) branches_used,(SELECT COUNT_BIG(*) FROM dbo.memberships m WHERE m.tenant_id=t.id AND m.status<>'INACTIVE' AND EXISTS(SELECT 1 FROM OPENJSON(m.roles) WHERE value='PRO')) professionals_used,(SELECT COUNT_BIG(*) FROM dbo.tenant_specialties x WHERE x.tenant_id=t.id) specialties_used,t.ruc,t.profile_revision AS revision FROM dbo.tenants t JOIN dbo.users u ON u.id=t.owner_user_id JOIN dbo.subscriptions s ON s.tenant_id=t.id JOIN dbo.plans p ON p.id=s.plan_id JOIN dbo.plan_versions v ON v.plan_id=s.plan_id AND v.version=s.plan_version WHERE @tenant_id IS NULL OR t.id=@tenant_id ORDER BY t.created_at DESC,t.id;
END;
GO
ALTER PROCEDURE dbo.usp_saas_tenant_create @tenant_id char(36),@branch_id char(36),@owner_id char(36),@input nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_saas_write_gate;
 DECLARE @public bit=CASE WHEN CONVERT(varchar(20),SESSION_CONTEXT(N'hp_scope'))='IDENTITY' AND SESSION_CONTEXT(N'hp_actor_id') IS NULL AND SESSION_CONTEXT(N'hp_tenant_id') IS NULL THEN 1 ELSE 0 END;
 IF @public=0 EXEC dbo.usp_require_actor @roles=N'SAD',@platform_only=1;
 EXEC dbo.usp_org_json_object @input,N'{"name":1,"ruc":1,"slug":1,"kind":1,"domain":1,"timezone":1,"branchName":1,"address":1,"specialties":4,"subscription":5}';
 DECLARE @ruc nvarchar(max),@name nvarchar(max),@slug nvarchar(max),@kind nvarchar(max),@domain nvarchar(max),@zone nvarchar(max),@bname nvarchar(max),@address nvarchar(max),@codes nvarchar(max),@sub nvarchar(max),@pid char(36),@ver int,@cycle nvarchar(7),@b int,@pr int,@sc int,@modules nvarchar(max),@owner_domain nvarchar(6),@verified bit,@user_exists char(36);
 SELECT @ruc=ruc,@name=name,@slug=slug,@kind=kind,@domain=domain,@zone=timezone,@bname=branchName,@address=address,@codes=specialties,@sub=subscription FROM OPENJSON(@input) WITH(ruc nvarchar(max),name nvarchar(max),slug nvarchar(max),kind nvarchar(max),domain nvarchar(max),timezone nvarchar(max),branchName nvarchar(max),address nvarchar(max),specialties nvarchar(max) AS JSON,subscription nvarchar(max) AS JSON);
 IF @ruc IS NULL OR DATALENGTH(@ruc)<>22 OR @ruc COLLATE Latin1_General_100_BIN2 LIKE N'%[^0-9]%' THROW 51000,N'HP_INVALID:RUC format',1;
 IF @tenant_id IS NULL OR @branch_id IS NULL OR @owner_id IS NULL OR NULLIF(LTRIM(RTRIM(@name)),N'') IS NULL OR DATALENGTH(@name)>320 OR NULLIF(LTRIM(RTRIM(@bname)),N'') IS NULL OR DATALENGTH(@bname)>320 OR DATALENGTH(@address)>600 OR NULLIF(LTRIM(RTRIM(@zone)),N'') IS NULL OR DATALENGTH(@zone)>128 OR DATALENGTH(@kind)<>2*LEN(@kind) OR DATALENGTH(@domain)<>2*LEN(@domain) OR @kind COLLATE Latin1_General_100_BIN2 NOT IN ('DOCTOR','CLINIC','HOSPITAL','VETERINARY','DENTAL','SPECIALTY_CENTER') OR @domain COLLATE Latin1_General_100_BIN2 NOT IN ('HUMAN','ANIMAL') OR (@kind='VETERINARY' AND @domain<>'ANIMAL') OR (@kind NOT IN ('DOCTOR','VETERINARY') AND @domain<>'HUMAN') THROW 51000,'HP_INVALID:Datos de organizacion invalidos',1;
 IF LEN(@slug) NOT BETWEEN 1 AND 63 OR DATALENGTH(@slug)<>2*LEN(@slug) OR @slug COLLATE Latin1_General_100_BIN2 LIKE N'%[^a-z0-9-]%' OR LEFT(@slug,1)='-' OR RIGHT(@slug,1)='-' OR @slug LIKE N'%--%' OR @slug IN ('www','admin','api','app','saas','mail','support','status','auth','portal','localhost') THROW 51000,'HP_INVALID:Subdominio invalido o reservado',1;
 SELECT @user_exists=id,@owner_domain=clinical_domain,@verified=email_verified FROM dbo.users WITH(UPDLOCK,HOLDLOCK) WHERE id=@owner_id AND active=1 AND platform_role IS NULL;
 IF @user_exists IS NULL OR (@kind='DOCTOR' AND (@owner_domain IS NULL OR @owner_domain<>@domain)) THROW 51000,'HP_INVALID:Propietario o dominio incompatible',1;
 IF @public=1 AND (@verified<>0 OR EXISTS(SELECT 1 FROM dbo.memberships WITH(UPDLOCK,HOLDLOCK) WHERE user_id=@owner_id) OR EXISTS(SELECT 1 FROM dbo.tenants WITH(UPDLOCK,HOLDLOCK) WHERE owner_user_id=@owner_id)) THROW 51001,'HP_FORBIDDEN:El registro requiere identidad nueva sin membresias',1;
 IF EXISTS(SELECT 1 FROM dbo.branches WITH(UPDLOCK,HOLDLOCK) WHERE id=@branch_id) THROW 51003,'HP_CONFLICT:Identificador de sede existente',1; IF EXISTS(SELECT 1 FROM dbo.tenants WITH(UPDLOCK,HOLDLOCK) WHERE slug=@slug OR id=@tenant_id) THROW 51003,'HP_CONFLICT:Subdominio o cliente existente',1;
 IF EXISTS(SELECT 1 FROM dbo.tenants WITH(UPDLOCK,HOLDLOCK,INDEX(UQ_tenants_ruc)) WHERE ruc=@ruc COLLATE Latin1_General_100_BIN2) THROW 51003,N'HP_CONFLICT:RUC unavailable',1;
 EXEC dbo.usp_org_subscription_resolve @sub,@kind,@domain,@public,@pid OUTPUT,@ver OUTPUT,@cycle OUTPUT,@b OUTPUT,@pr OUTPUT,@sc OUTPUT,@modules OUTPUT;
 EXEC dbo.usp_org_validate_specialties @codes,@domain,@kind,@sc,@modules;
 INSERT dbo.tenants(id,name,slug,kind,domain,owner_user_id,timezone,ruc) VALUES(@tenant_id,@name,@slug,@kind,@domain,@owner_id,@zone,@ruc);
 INSERT dbo.subscriptions(tenant_id,plan_id,plan_version,cycle,branch_quota,professional_quota,specialty_quota,renewal_date) VALUES(@tenant_id,@pid,@ver,@cycle,@b,@pr,@sc,CONVERT(date,CASE WHEN @cycle='YEARLY' THEN DATEADD(year,1,SYSUTCDATETIME()) ELSE DATEADD(month,1,SYSUTCDATETIME()) END));
 INSERT dbo.branches(id,tenant_id,name,address,[external],active) VALUES(@branch_id,@tenant_id,@bname,@address,0,1);
 INSERT dbo.tenant_specialties(tenant_id,specialty_code) SELECT @tenant_id,value FROM OPENJSON(@codes);
 INSERT dbo.areas(id,tenant_id,branch_id,name,specialties) VALUES(LOWER(CONVERT(char(36),NEWID())),@tenant_id,@branch_id,N'Consulta y atencion',@codes);
 INSERT dbo.memberships(tenant_id,user_id,roles,status,owner) VALUES(@tenant_id,@owner_id,CASE WHEN @kind='DOCTOR' THEN N'["ADM","PRO"]' ELSE N'["ADM"]' END,'ACTIVE',1);
 INSERT dbo.membership_branches(tenant_id,user_id,branch_id) VALUES(@tenant_id,@owner_id,@branch_id);
 IF @kind='DOCTOR' INSERT dbo.membership_specialties(tenant_id,user_id,specialty_code) SELECT @tenant_id,@owner_id,value FROM OPENJSON(@codes);
 DECLARE @meta nvarchar(max)=(SELECT @slug slug FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @tenant_id,N'TENANT_CREATED',@tenant_id,@meta;
 IF @public=0 EXEC dbo.usp_platform_tenants @tenant_id; ELSE SELECT id,id AS tenant_id,slug,kind,domain,status,ruc,profile_revision AS revision FROM dbo.tenants WHERE id=@tenant_id;
END;
GO
ALTER PROCEDURE dbo.usp_platform_audit @limit int=100
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_actor @roles=N'SAD',@platform_only=1; SET @limit=CASE WHEN @limit IS NULL THEN 100 WHEN @limit<1 THEN 1 WHEN @limit>200 THEN 200 ELSE @limit END; SELECT TOP(@limit) id,tenant_id,actor_id,action,target_id,metadata,created_at FROM dbo.audit_events WHERE action IN ('TENANT_PROFILE_UPDATED','TENANT_CREATED','TENANT_STATUS_CHANGED','PLAN_VERSION_CREATED','SUBSCRIPTION_CHANGED','BRANCH_SAVED','AREA_SAVED','MEMBERSHIP_SAVED','SPECIALTIES_CONFIGURED','SAAS_PAYMENT_RECORDED') ORDER BY id DESC;
END;
GO
-- Existing three-argument signature retained for platform sessions only.
ALTER PROCEDURE dbo.usp_session_save @token_hash char(64),@user_id char(36),@expires_at datetime2(6)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_transaction; IF XACT_STATE()<>1 THROW 51000,N'HP_INVALID:Committable transaction required',1;
 IF SESSION_CONTEXT(N'hp_tenant_id') IS NOT NULL THROW 51001,N'HP_FORBIDDEN:Tenant login requires the RUC session entry',1;
 EXEC dbo.usp_require_scope 'IDENTITY'; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')); IF @expires_at<=SYSUTCDATETIME() THROW 51000,'HP_INVALID:Session expiry',1; IF NOT EXISTS(SELECT 1 FROM dbo.users WITH(UPDLOCK,HOLDLOCK) WHERE id=@user_id AND active=1 AND email_verified=1 AND (locked_until IS NULL OR locked_until<=SYSUTCDATETIME()) AND ((@t IS NULL AND platform_role IN ('SAD','SOP')) OR (@t IS NOT NULL AND platform_role IS NULL AND EXISTS(SELECT 1 FROM dbo.memberships WHERE tenant_id=@t AND user_id=@user_id AND status='ACTIVE')))) THROW 51001,'HP_FORBIDDEN:Login eligibility changed',1; INSERT dbo.auth_sessions(token_hash,user_id,tenant_id,expires_at,csrf_token,user_agent,source_ip) VALUES(@token_hash,@user_id,@t,@expires_at,CONVERT(char(64),CRYPT_GEN_RANDOM(32),2),COALESCE(CONVERT(nvarchar(300),SESSION_CONTEXT(N'hp_user_agent')),N''),COALESCE(CONVERT(nvarchar(80),SESSION_CONTEXT(N'hp_source_ip')),N'')); UPDATE dbo.users SET login_failures=0,locked_until=NULL WHERE id=@user_id; EXEC dbo.usp_audit_event @t,N'LOGIN_SUCCEEDED',@user_id,@actor_override=@user_id; SELECT csrf_token,expires_at FROM dbo.auth_sessions WHERE token_hash=@token_hash;
END;
GO
-- Tenant session writer: explicit RUC input and same prior response columns.
-- The old three-argument entry rejects tenant context and remains platform-only.
CREATE PROCEDURE dbo.usp_tenant_session_save @token_hash char(64),@user_id char(36),@expires_at datetime2(6),@ruc nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_transaction;
 IF XACT_STATE()<>1 THROW 51000,N'HP_INVALID:Committable transaction required',1;
 DECLARE @scope nvarchar(max)=CONVERT(nvarchar(max),SESSION_CONTEXT(N'hp_scope')),
 @raw nvarchar(max)=CONVERT(nvarchar(max),SESSION_CONTEXT(N'hp_tenant_id')),
 @request nvarchar(max)=CONVERT(nvarchar(max),SESSION_CONTEXT(N'hp_request_id')),@t char(36);
 IF @scope IS NULL OR @scope COLLATE Latin1_General_100_BIN2<>N'IDENTITY' OR DATALENGTH(@scope)<>16
  OR SESSION_CONTEXT(N'hp_actor_id') IS NOT NULL
  OR @request IS NULL OR DATALENGTH(@request)<>72 OR TRY_CONVERT(uniqueidentifier,@request) IS NULL
  OR @request COLLATE Latin1_General_100_BIN2<>LOWER(CONVERT(nvarchar(36),TRY_CONVERT(uniqueidentifier,@request))) COLLATE Latin1_General_100_BIN2
  THROW 51001,N'HP_FORBIDDEN:Anonymous identity context required',1;
 IF @raw IS NULL THROW 51001,N'HP_FORBIDDEN:Tenant identity context required',1;
 IF @raw IS NOT NULL
 BEGIN
  IF DATALENGTH(@raw)<>72 OR TRY_CONVERT(uniqueidentifier,@raw) IS NULL
   OR @raw COLLATE Latin1_General_100_BIN2<>LOWER(CONVERT(nvarchar(36),TRY_CONVERT(uniqueidentifier,@raw))) COLLATE Latin1_General_100_BIN2
   THROW 51001,N'HP_FORBIDDEN:Trusted tenant context required',1;
  SET @t=CONVERT(char(36),@raw);
  IF @ruc IS NULL OR DATALENGTH(@ruc)<>22 OR @ruc COLLATE Latin1_General_100_BIN2 LIKE N'%[^0-9]%'
   THROW 51000,N'HP_INVALID:RUC required for tenant session',1;
  IF NOT EXISTS(SELECT 1 FROM dbo.tenants WITH(UPDLOCK,HOLDLOCK) WHERE id=@t AND ruc=@ruc COLLATE Latin1_General_100_BIN2 AND status IN (N'TRIAL',N'ACTIVE'))
   THROW 51001,N'HP_FORBIDDEN:Login unavailable',1;
 END
 ELSE IF @ruc IS NOT NULL THROW 51001,N'HP_FORBIDDEN:Separate platform login required',1;
 IF @expires_at IS NULL OR @expires_at<=SYSUTCDATETIME() OR @token_hash IS NULL OR DATALENGTH(@token_hash)<>64
  OR @token_hash COLLATE Latin1_General_100_BIN2 LIKE '%[^0-9a-f]%'
  OR @user_id IS NULL OR TRY_CONVERT(uniqueidentifier,@user_id) IS NULL
  OR @user_id COLLATE Latin1_General_100_BIN2<>LOWER(CONVERT(char(36),TRY_CONVERT(uniqueidentifier,@user_id))) COLLATE Latin1_General_100_BIN2
  THROW 51000,N'HP_INVALID:Session parameters',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.users WITH(UPDLOCK,HOLDLOCK) WHERE id=@user_id AND active=1 AND email_verified=1
  AND (locked_until IS NULL OR locked_until<=SYSUTCDATETIME())
  AND ((@t IS NULL AND platform_role IN (N'SAD',N'SOP')) OR (@t IS NOT NULL AND platform_role IS NULL)))
  THROW 51001,N'HP_FORBIDDEN:Login eligibility changed',1;
 IF @t IS NOT NULL
 BEGIN
  DECLARE @roles nvarchar(max);
  SELECT @roles=roles FROM dbo.memberships WITH(HOLDLOCK) WHERE tenant_id=@t AND user_id=@user_id AND status=N'ACTIVE';
  IF @roles IS NULL OR ISJSON(@roles,ARRAY)<>1 OR NOT EXISTS(SELECT 1 FROM OPENJSON(@roles))
   OR EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE type<>1 OR value COLLATE Latin1_General_100_BIN2 NOT IN (N'ADM',N'REC',N'PRO',N'ASI',N'DIA',N'FAR',N'CAJ',N'ALM',N'PAC',N'RES',N'AUD'))
   THROW 51001,N'HP_FORBIDDEN:Login membership changed',1;
 END;
 INSERT dbo.auth_sessions(token_hash,user_id,tenant_id,expires_at,csrf_token,user_agent,source_ip)
 VALUES(@token_hash,@user_id,@t,@expires_at,CONVERT(char(64),CRYPT_GEN_RANDOM(32),2),COALESCE(CONVERT(nvarchar(300),SESSION_CONTEXT(N'hp_user_agent')),N''),COALESCE(CONVERT(nvarchar(80),SESSION_CONTEXT(N'hp_source_ip')),N''));
 UPDATE dbo.users SET login_failures=0,locked_until=NULL WHERE id=@user_id;
 EXEC dbo.usp_audit_event @t,N'LOGIN_SUCCEEDED',@user_id,@actor_override=@user_id;
 IF XACT_STATE()<>1 THROW 51000,N'HP_INVALID:Committable transaction required',1;
 SELECT csrf_token,expires_at FROM dbo.auth_sessions WHERE token_hash=@token_hash;
END;
GO

-- Locks follow tenant -> account -> membership for tenant login. The outer
-- Spring transaction retains them through password verification/session save.
-- Deadlocks and unknown results are never retried here. Future two-connection
-- QA must verify this policy; static parsing is not concurrency evidence.
CREATE PROCEDURE dbo.usp_identity_tenant_ruc_lock @ruc nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_transaction;
 IF XACT_STATE()<>1 THROW 51000,N'HP_INVALID:Committable transaction required',1;
 DECLARE @scope nvarchar(max)=CONVERT(nvarchar(max),SESSION_CONTEXT(N'hp_scope')),
 @raw nvarchar(max)=CONVERT(nvarchar(max),SESSION_CONTEXT(N'hp_tenant_id')),
 @request nvarchar(max)=CONVERT(nvarchar(max),SESSION_CONTEXT(N'hp_request_id'));
 IF @scope IS NULL OR @scope COLLATE Latin1_General_100_BIN2<>N'IDENTITY' OR DATALENGTH(@scope)<>16
  OR SESSION_CONTEXT(N'hp_actor_id') IS NOT NULL OR @raw IS NULL OR DATALENGTH(@raw)<>72
  OR TRY_CONVERT(uniqueidentifier,@raw) IS NULL
  OR @raw COLLATE Latin1_General_100_BIN2<>LOWER(CONVERT(nvarchar(36),TRY_CONVERT(uniqueidentifier,@raw))) COLLATE Latin1_General_100_BIN2
  OR @request IS NULL OR DATALENGTH(@request)<>72 OR TRY_CONVERT(uniqueidentifier,@request) IS NULL
  OR @request COLLATE Latin1_General_100_BIN2<>LOWER(CONVERT(nvarchar(36),TRY_CONVERT(uniqueidentifier,@request))) COLLATE Latin1_General_100_BIN2
  THROW 51001,N'HP_FORBIDDEN:Anonymous trusted tenant identity context required',1;
 IF @ruc IS NULL OR DATALENGTH(@ruc)<>22 OR @ruc COLLATE Latin1_General_100_BIN2 LIKE N'%[^0-9]%'
  THROW 51000,N'HP_INVALID:RUC format',1;
 SELECT id,ruc,profile_revision AS revision FROM dbo.tenants WITH(UPDLOCK,HOLDLOCK)
 WHERE id=CONVERT(char(36),@raw) AND ruc=@ruc COLLATE Latin1_General_100_BIN2 AND status IN (N'TRIAL',N'ACTIVE');
END;
GO
-- Public destination only. No account/email lookup, password, actor or session.
CREATE PROCEDURE dbo.usp_tenant_space_resolve @ruc nvarchar(max),@base_domain nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_transaction;
 IF XACT_STATE()<>1 THROW 51000,N'HP_INVALID:Committable transaction required',1;
 DECLARE @scope nvarchar(max)=CONVERT(nvarchar(max),SESSION_CONTEXT(N'hp_scope')),
 @request nvarchar(max)=CONVERT(nvarchar(max),SESSION_CONTEXT(N'hp_request_id'));
 IF @scope IS NULL OR @scope COLLATE Latin1_General_100_BIN2<>N'IDENTITY' OR DATALENGTH(@scope)<>16
  OR SESSION_CONTEXT(N'hp_actor_id') IS NOT NULL OR SESSION_CONTEXT(N'hp_tenant_id') IS NOT NULL
  OR @request IS NULL OR DATALENGTH(@request)<>72 OR TRY_CONVERT(uniqueidentifier,@request) IS NULL
  OR @request COLLATE Latin1_General_100_BIN2<>LOWER(CONVERT(nvarchar(36),TRY_CONVERT(uniqueidentifier,@request))) COLLATE Latin1_General_100_BIN2
  THROW 51001,N'HP_FORBIDDEN:Anonymous platform identity context required',1;
 IF @ruc IS NULL OR DATALENGTH(@ruc)<>22 OR @ruc COLLATE Latin1_General_100_BIN2 LIKE N'%[^0-9]%'
  OR @base_domain IS NULL OR DATALENGTH(@base_domain) NOT BETWEEN 6 AND 506
  OR @base_domain COLLATE Latin1_General_100_BIN2 LIKE N'%[^a-z0-9.-]%'
  OR @base_domain NOT LIKE N'%.%' OR @base_domain LIKE N'%..%' OR @base_domain LIKE N'.%' OR @base_domain LIKE N'%.'
  OR @base_domain LIKE N'-%' OR @base_domain LIKE N'%-' OR @base_domain LIKE N'%.-%' OR @base_domain LIKE N'%-.%'
  THROW 51000,N'HP_INVALID:RUC or canonical base domain format',1;
 SELECT CONVERT(nvarchar(253),t.slug+N'.'+@base_domain) AS hostname
 FROM dbo.tenants t WITH(HOLDLOCK) JOIN dbo.subscriptions s ON s.tenant_id=t.id
 WHERE t.ruc=@ruc COLLATE Latin1_General_100_BIN2 AND t.status IN (N'TRIAL',N'ACTIVE')
 AND DATALENGTH(CONVERT(nvarchar(max),t.slug)+N'.'+@base_domain)<=506;
END;
GO
CREATE PROCEDURE dbo.usp_tenant_profile_save @tenant_id char(36),@input nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_transaction;
 IF XACT_STATE()<>1 THROW 51000,N'HP_INVALID:Committable transaction required',1;
 DECLARE @scope nvarchar(max)=CONVERT(nvarchar(max),SESSION_CONTEXT(N'hp_scope')),
 @actor_raw nvarchar(max)=CONVERT(nvarchar(max),SESSION_CONTEXT(N'hp_actor_id')),
 @token_raw nvarchar(max)=CONVERT(nvarchar(max),SESSION_CONTEXT(N'hp_token_hash')),
 @request nvarchar(max)=CONVERT(nvarchar(max),SESSION_CONTEXT(N'hp_request_id'));
 IF @scope IS NULL OR @scope COLLATE Latin1_General_100_BIN2<>N'REQUEST' OR DATALENGTH(@scope)<>14
  OR SESSION_CONTEXT(N'hp_tenant_id') IS NOT NULL OR @actor_raw IS NULL OR DATALENGTH(@actor_raw)<>72
  OR TRY_CONVERT(uniqueidentifier,@actor_raw) IS NULL
  OR @actor_raw COLLATE Latin1_General_100_BIN2<>LOWER(CONVERT(nvarchar(36),TRY_CONVERT(uniqueidentifier,@actor_raw))) COLLATE Latin1_General_100_BIN2
  OR @token_raw IS NULL OR DATALENGTH(@token_raw)<>128 OR @token_raw COLLATE Latin1_General_100_BIN2 LIKE N'%[^0-9a-f]%'
  OR @request IS NULL OR DATALENGTH(@request)<>72 OR TRY_CONVERT(uniqueidentifier,@request) IS NULL
  OR @request COLLATE Latin1_General_100_BIN2<>LOWER(CONVERT(nvarchar(36),TRY_CONVERT(uniqueidentifier,@request))) COLLATE Latin1_General_100_BIN2
  THROW 51001,N'HP_FORBIDDEN:Trusted platform request context required',1;
 EXEC dbo.usp_require_actor @roles=N'SAD',@platform_only=1;
 EXEC dbo.usp_saas_write_gate;
 -- Retain and revalidate actual authority. hp_actor_roles is never a grant.
 IF NOT EXISTS(SELECT 1 FROM dbo.users WITH(HOLDLOCK) WHERE id=CONVERT(char(36),@actor_raw) AND active=1 AND email_verified=1 AND platform_role=N'SAD')
  OR NOT EXISTS(SELECT 1 FROM dbo.auth_sessions WITH(HOLDLOCK) WHERE token_hash=CONVERT(char(64),@token_raw) AND user_id=CONVERT(char(36),@actor_raw) AND tenant_id IS NULL AND revoked=0 AND expires_at>SYSUTCDATETIME())
  THROW 51001,N'HP_FORBIDDEN:Current SAD authority required',1;
 IF @tenant_id IS NULL OR TRY_CONVERT(uniqueidentifier,@tenant_id) IS NULL
  OR @tenant_id COLLATE Latin1_General_100_BIN2<>LOWER(CONVERT(char(36),TRY_CONVERT(uniqueidentifier,@tenant_id))) COLLATE Latin1_General_100_BIN2
  THROW 51000,N'HP_INVALID:Canonical tenant UUID required',1;
 IF @input IS NULL OR ISJSON(@input,OBJECT)<>1 OR (SELECT COUNT(*) FROM OPENJSON(@input))<>4
  OR EXISTS(SELECT [key] COLLATE Latin1_General_100_BIN2 FROM OPENJSON(@input) GROUP BY [key] COLLATE Latin1_General_100_BIN2 HAVING COUNT(*)<>1)
  OR EXISTS(SELECT 1 FROM OPENJSON(@input) WHERE [key] COLLATE Latin1_General_100_BIN2 NOT IN (N'name',N'ruc',N'timezone',N'expectedRevision')
    OR ([key] COLLATE Latin1_General_100_BIN2=N'expectedRevision' AND type<>2)
    OR ([key] COLLATE Latin1_General_100_BIN2<>N'expectedRevision' AND type<>1))
  THROW 51000,N'HP_INVALID:Closed profile command required',1;
 DECLARE @name nvarchar(max),@ruc nvarchar(max),@zone nvarchar(max),@lexical nvarchar(max),@expected int;
 SELECT @name=MAX(CASE WHEN [key] COLLATE Latin1_General_100_BIN2=N'name' THEN value END),
  @ruc=MAX(CASE WHEN [key] COLLATE Latin1_General_100_BIN2=N'ruc' THEN value END),
  @zone=MAX(CASE WHEN [key] COLLATE Latin1_General_100_BIN2=N'timezone' THEN value END),
  @lexical=MAX(CASE WHEN [key] COLLATE Latin1_General_100_BIN2=N'expectedRevision' THEN value END) FROM OPENJSON(@input);
 SET @expected=TRY_CONVERT(int,@lexical);
 IF @name IS NULL OR NULLIF(LTRIM(RTRIM(@name)),N'') IS NULL OR DATALENGTH(@name)>320
  OR @zone IS NULL OR NULLIF(LTRIM(RTRIM(@zone)),N'') IS NULL OR DATALENGTH(@zone)>128
  OR @ruc IS NULL OR DATALENGTH(@ruc)<>22 OR @ruc COLLATE Latin1_General_100_BIN2 LIKE N'%[^0-9]%'
  OR @expected IS NULL OR @expected<1 OR DATALENGTH(@lexical)<>DATALENGTH(CONVERT(nvarchar(10),@expected))
  OR @lexical COLLATE Latin1_General_100_BIN2<>CONVERT(nvarchar(10),@expected) COLLATE Latin1_General_100_BIN2
  THROW 51000,N'HP_INVALID:Profile values or integer revision invalid',1;
 DECLARE @previous int,@before_name nvarchar(160),@before_ruc varchar(11),@before_zone nvarchar(64);
 SELECT @previous=profile_revision,@before_name=name,@before_ruc=ruc,@before_zone=timezone FROM dbo.tenants WITH(UPDLOCK,HOLDLOCK) WHERE id=@tenant_id;
 IF @previous IS NULL THROW 51002,N'HP_NOT_FOUND:Tenant not available',1;
 IF @previous<>@expected OR @previous=2147483647 THROW 51003,N'HP_CONFLICT:Profile revision changed',1;
 IF EXISTS(SELECT 1 FROM dbo.tenants WITH(UPDLOCK,HOLDLOCK,INDEX(UQ_tenants_ruc)) WHERE ruc=@ruc COLLATE Latin1_General_100_BIN2 AND id<>@tenant_id)
  THROW 51003,N'HP_CONFLICT:RUC unavailable',1;
 UPDATE dbo.tenants SET name=@name,ruc=@ruc,timezone=@zone,profile_revision=profile_revision+1 WHERE id=@tenant_id AND profile_revision=@expected;
 IF @@ROWCOUNT<>1 THROW 51003,N'HP_CONFLICT:Profile revision changed',1;
 -- Scalars only, as required by the existing audit helper. No credential/body.
 DECLARE @metadata nvarchar(max)=(SELECT @before_name AS previousName,@before_ruc AS previousRuc,@before_zone AS previousTimezone,@previous AS previousRevision,@name AS name,@ruc AS ruc,@zone AS timezone,@previous+1 AS revision FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
 EXEC dbo.usp_audit_event @tenant_id=@tenant_id,@action=N'TENANT_PROFILE_UPDATED',@target_id=@tenant_id,@metadata=@metadata;
 IF XACT_STATE()<>1 THROW 51000,N'HP_INVALID:Committable transaction required',1;
 EXEC dbo.usp_platform_tenants @tenant_id;
END;
GO

IF @@TRANCOUNT=0 OR XACT_STATE()<>1 THROW 51000,N'HP_INVALID:External committable migration transaction required',1;
GRANT EXECUTE ON OBJECT::dbo.usp_tenant_session_save TO hp_runtime_executor;
DENY EXECUTE ON OBJECT::dbo.usp_tenant_session_save TO hp_bootstrap_executor;
GRANT EXECUTE ON OBJECT::dbo.usp_identity_tenant_ruc_lock TO hp_runtime_executor;
DENY EXECUTE ON OBJECT::dbo.usp_identity_tenant_ruc_lock TO hp_bootstrap_executor;
GRANT EXECUTE ON OBJECT::dbo.usp_tenant_space_resolve TO hp_runtime_executor;
DENY EXECUTE ON OBJECT::dbo.usp_tenant_space_resolve TO hp_bootstrap_executor;
GRANT EXECUTE ON OBJECT::dbo.usp_tenant_profile_save TO hp_runtime_executor;
DENY EXECUTE ON OBJECT::dbo.usp_tenant_profile_save TO hp_bootstrap_executor;
GO
